//! Temporary steady-state TCP diagnostic; shared verbatim by both revisions.
#![allow(clippy::ptr_arg)]

use std::{
    io::{BufRead, BufReader, Write},
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};

use ruapc::{Client, Context, Endpoint, ListenMode, Router, Server, SocketPoolConfig, Transport};

const TASKS: usize = 1024;
const WARMUP_PER_TASK: usize = 256;
const MEASURED_PER_TASK: usize = 8192;

#[ruapc::service]
trait EchoService {
    async fn echo(&self, ctx: &ruapc::Context, req: &String) -> ruapc::Result<String>;
}

struct EchoImpl;

impl EchoService for EchoImpl {
    async fn echo(&self, _ctx: &ruapc::Context, req: &String) -> ruapc::Result<String> {
        Ok(req.clone())
    }
}

struct PerfControl {
    command: std::fs::File,
    acknowledgment: BufReader<std::fs::File>,
}

impl PerfControl {
    fn from_env() -> Option<Self> {
        let directory = std::env::var_os("RUAPC_STEADY_PERF_DIR").map(PathBuf::from)?;
        Some(Self {
            command: std::fs::OpenOptions::new()
                .write(true)
                .open(directory.join("control.fifo"))
                .unwrap(),
            acknowledgment: BufReader::new(
                std::fs::File::open(directory.join("ack.fifo")).unwrap(),
            ),
        })
    }

    fn command(&mut self, command: &[u8]) {
        self.command.write_all(command).unwrap();
        self.command.flush().unwrap();
        let mut acknowledgment = String::new();
        self.acknowledgment.read_line(&mut acknowledgment).unwrap();
        assert_eq!(
            acknowledgment.trim_matches(|ch: char| ch == '\0' || ch.is_whitespace()),
            "ack",
        );
    }
}

async fn wait_for_thread_placement() {
    let Some(directory) = std::env::var_os("RUAPC_STEADY_CONTROL_DIR").map(PathBuf::from) else {
        panic!("run through run.py so worker placement is verified before warmup");
    };
    std::fs::write(directory.join("pid"), std::process::id().to_string()).unwrap();
    let deadline = Instant::now() + Duration::from_secs(30);
    while !directory.join("placed").exists() {
        assert!(
            Instant::now() < deadline,
            "thread-placement handshake timed out"
        );
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
}

async fn run() {
    let echo = Arc::new(EchoImpl);
    let mut router = Router::default();
    echo.ruapc_export(&mut router);
    let config = SocketPoolConfig {
        listen_mode: ListenMode::UNIFIED,
        buffer_pool_memory: 1 << 30,
        ..Default::default()
    };
    #[cfg(feature = "rdma")]
    let config = {
        let mut config = config;
        config
            .rdma
            .get_or_insert_with(Default::default)
            .path
            .device_filter = vec!["mlx5_0".to_string()];
        config
    };

    let server = Server::create(router, &config).unwrap();
    let addr = server.listen("127.0.0.1:0".parse().unwrap()).await.unwrap();
    let ctx = Context::create(&config)
        .unwrap()
        .with_endpoint(Endpoint::new(Transport::TCP, addr));
    Client::default()
        .echo(&ctx, &"probe".to_string())
        .await
        .unwrap();
    wait_for_thread_placement().await;

    let request = Arc::new("x".repeat(16));
    let warmed = Arc::new(tokio::sync::Barrier::new(TASKS + 1));
    let start_gate = Arc::new(tokio::sync::Barrier::new(TASKS + 1));
    let mut tasks = Vec::with_capacity(TASKS);
    for _ in 0..TASKS {
        let ctx = ctx.clone();
        let request = request.clone();
        let warmed = warmed.clone();
        let start_gate = start_gate.clone();
        tasks.push(tokio::spawn(async move {
            let client = Client::default();
            for _ in 0..WARMUP_PER_TASK {
                std::hint::black_box(client.echo(&ctx, &request).await.unwrap());
            }
            warmed.wait().await;
            start_gate.wait().await;
            for _ in 0..MEASURED_PER_TASK {
                std::hint::black_box(client.echo(&ctx, &request).await.unwrap());
            }
        }));
    }

    warmed.wait().await;
    let mut perf = PerfControl::from_env();
    if let Some(perf) = &mut perf {
        perf.command(b"enable\n");
    }
    let start = Instant::now();
    start_gate.wait().await;
    for task in tasks {
        task.await.unwrap();
    }
    let seconds = start.elapsed().as_secs_f64();
    if let Some(perf) = &mut perf {
        perf.command(b"disable\n");
    }
    let operations = TASKS * MEASURED_PER_TASK;
    println!(
        "RESULT {{\"tasks\":{TASKS},\"payload_bytes\":16,\"warmup_per_task\":{WARMUP_PER_TASK},\"measured_per_task\":{MEASURED_PER_TASK},\"operations\":{operations},\"seconds\":{seconds:.9},\"kops_per_sec\":{:.6}}}",
        operations as f64 / seconds / 1000.0,
    );
    server.stop();
    server.join().await;
}

fn main() {
    tokio::runtime::Builder::new_multi_thread()
        .worker_threads(8)
        .enable_all()
        .build()
        .unwrap()
        .block_on(run());
}

