#!/usr/bin/env python3
"""Normalize raw perf counts by completed requests; retain every sample."""
import argparse
import csv
import json
import statistics
from pathlib import Path

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("directory", type=Path)
args = parser.parse_args()
summary = json.loads((args.directory / "summary.json").read_text())
rows = []
for run in summary["runs"]:
    events = {}
    with (Path(run["directory"]) / "perf.csv").open() as source:
        for fields in csv.reader(source, delimiter=";"):
            if len(fields) < 5 or fields[0].startswith("#"):
                continue
            events[fields[2]] = {
                "count": float(fields[0]), "unit": fields[1],
                "running_nanoseconds": int(fields[3]),
                "percent_running": float(fields[4]),
            }
    operations = run["operations"]
    rows.append({
        **run,
        "events": events,
        "instructions_per_request": events["instructions"]["count"] / operations,
        "cpu_microseconds_per_request": events["task-clock"]["count"] * 1000 / operations,
        "context_switches_per_request": events["context-switches"]["count"] / operations,
        "page_faults_per_request": events["page-faults"]["count"] / operations,
    })

fields = ("instructions_per_request", "kops_per_sec", "cpu_microseconds_per_request",
          "context_switches_per_request", "page_faults_per_request")
statistics_by_version = {}
for version in ("baseline", "current"):
    statistics_by_version[version] = {}
    for field in fields:
        values = [row[field] for row in rows if row["version"] == version]
        statistics_by_version[version][field] = {
            "median": statistics.median(values), "min": min(values), "max": max(values), "samples": values,
        }
paired = {}
for field in fields:
    ratios = []
    for pair in sorted({row["pair"] for row in rows}):
        values = {row["version"]: row[field] for row in rows if row["pair"] == pair}
        if values["baseline"]:
            ratios.append(values["current"] / values["baseline"])
    paired[field] = {"median_current_over_baseline": statistics.median(ratios), "samples": ratios}
result = {
    "source_summary": str(args.directory / "summary.json"),
    "build_provenance": "/tmp/ruapc-tcp-steady-plan/stat-build-provenance.json",
    "all_instructions_running_100_percent": all(row["events"]["instructions"]["percent_running"] == 100 for row in rows),
    "statistics": statistics_by_version,
    "paired_ratios": paired,
    "samples": rows,
}
(args.directory / "normalized.json").write_text(json.dumps(result, indent=2) + "\n")
print(json.dumps({key: value for key, value in result.items() if key != "samples"}, indent=2))
